package android.view;import android.content.Context;import java.util.ArrayList;import java.util.List;public class ViewGroup extends View {private final List<View> children=new ArrayList<View>();public ViewGroup(Context c){super(c);}public void addView(View v){children.add(v);v.setParent(this);if(isAttachedToWindow())v.attach();}public void removeView(View v){if(children.remove(v)){v.detach();v.setParent(null);}}public void removeAllViews(){for(View v:new ArrayList<View>(children))removeView(v);}public int getChildCount(){return children.size();}public View getChildAt(int i){return children.get(i);}@Override public <T extends View>T findViewById(int id){T self=super.findViewById(id);if(self!=null)return self;for(View v:children){T r=v.findViewById(id);if(r!=null)return r;}return null;}@Override public void attach(){super.attach();for(View v:children)v.attach();}@Override public void detach(){for(View v:children)v.detach();super.detach();}}
